package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionWorksheetRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Isolated request/DTO checks only. Real PG/OIDC/CSRF HTTP validation is separate. */
class InspectionWorksheetControllerTest {
    static final String ACTOR="78000000-0000-4000-8000-000000000001",TENANT="78000000-0000-4000-8000-000000000002",ID="78000000-0000-4000-8000-000000000003",TEMPLATE="78000000-0000-4000-8000-000000000004",ASSET="78000000-0000-4000-8000-000000000005";
    PlatformRepository platform;InspectionWorksheetRepository repository;InspectionWorksheetController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(InspectionWorksheetRepository.class);controller=new InspectionWorksheetController(platform,repository);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});when(repository.create(any(),anyLong(),any())).thenAnswer(call->row(1,"CREATE",false,((Creation)call.getArgument(2)).content(),definition()));when(repository.update(any(),any(),anyLong(),any())).thenAnswer(call->row(2,"UPDATE",false,call.getArgument(3),definition()));when(repository.restore(any(),any(),anyLong(),any())).thenAnswer(call->row(3,"RESTORE",false,call.getArgument(3),definition()));when(repository.archive(any(),any(),anyLong())).thenReturn(row(2,"ARCHIVE",true,new Content(Map.of(),null),definition()));}
    Access access(){return new Access(ACTOR,TENANT,7,"worksheet-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/inspection-worksheets");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","worksheet-test");r.addHeader("Idempotency-Key","worksheet-test-key");return r;}
    InspectionTemplate definition(){return new InspectionTemplate("new_device","合成模板",List.of(new InspectionTemplate.Item("firmware","安全","固件",null),new InspectionTemplate.Item("backup","备份","验证","")));}
    Entry row(long version,String action,boolean archived,Content content,InspectionTemplate definition){Instant time=Instant.parse("2026-10-04T08:00:00.123Z");var snapshot=InspectionTemplate.Snapshot.capture(UUID.fromString(TENANT),UUID.fromString(TEMPLATE),1,definition);var sheet=new InspectionWorksheet(UUID.fromString(TENANT),UUID.fromString(ASSET),"合成资产",snapshot,content.observations());return new Entry(ID,TENANT,ACTOR,version,time,time,ACTOR,time,action,archived,new InspectionWorksheetContent(sheet,content.reportedPerformedAt()));}
    ObjectNode input(){var v=mapper.createObjectNode().put("expected_version",0).put("asset_id",ASSET).put("template_id",TEMPLATE).put("template_version",1).putNull("reported_performed_at");v.putArray("observations").addObject().put("key","firmware").put("result","ATTENTION").putNull("note");return v;}
    ObjectNode update(){var v=input().put("expected_version",1);v.remove(List.of("asset_id","template_id","template_version"));return v;}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void createKeepsUnknownTimeUnansweredAndUnverifiedFacts(){var d=data(controller.write(null,"CREATE",input(),request("POST")));assertEquals(ID,d.get("id"));assertNull(d.get("reported_performed_at"));assertEquals("NOT_PROVIDED",d.get("time_source"));assertEquals("SELF_REPORTED_UNVERIFIED",d.get("verification_status"));assertEquals("UNVERIFIED",d.get("template_applicability_status"));assertEquals("NOT_IMPLEMENTED",d.get("evidence_binding_status"));assertEquals(false,d.get("report_published"));assertEquals(false,d.get("active_scan_performed"));assertEquals(1,((Map<?,?>)d.get("summary")).get("unanswered"));assertEquals(0,((Map<?,?>)d.get("summary")).get("normal"));verify(repository).authorizeWrite(access(),null);}
    @Test void updateRestoreReplaceOnlyExplicitContentAndArchiveAcceptsVersionOnly(){assertEquals(2L,data(controller.write(ID,"UPDATE",update(),request("PATCH"))).get("version"));assertEquals(3L,data(controller.write(ID,"RESTORE",update(),request("POST"))).get("version"));assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("archived"));assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",input().put("expected_version",1),request("PATCH")));assertThrows(DomainException.class,()->controller.write(ID,"ARCHIVE",update(),request("POST")));}
    @Test void otherRolesFailBeforeParsingAndNoRepositoryCalls(){for(String role:List.of("msp","tadmin","viewer","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));var r=request("POST");r.setContent("broken".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(r)).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);}verifyNoInteractions(repository);}
    @Test void missingInactiveOrMalformedSessionFails(){var r=request("GET");r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);verifyNoInteractions(repository);}
    @Test void versionTypesBoundsMissingFieldsAndUnsupportedScopeFactsFail(){for(JsonNode version:List.of(IntNode.valueOf(1),IntNode.valueOf(-1),TextNode.valueOf("0"),DoubleNode.valueOf(0.0))){var v=input();v.set("expected_version",version);assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}for(String key:List.of("expected_version","asset_id","template_id","template_version","observations","reported_performed_at")){var v=input();v.remove(key);assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}for(String key:List.of("tenant_id","asset_name","content_sha256","verification_status","report_published","summary"))assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put(key,"forged"),request("POST")));assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",update().put("expected_version",9007199254740990L),request("PATCH")));assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("template_version",0),request("POST")));}
    @Test void observationsRequireExactFieldsUniqueKeysEnumsAndNoEvidence(){for(String field:List.of("key","result","note")){var v=input();((ObjectNode)v.path("observations").get(0)).remove(field);assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}var evidence=input();((ObjectNode)evidence.path("observations").get(0)).putArray("evidence_ids");assertThrows(DomainException.class,()->controller.write(null,"CREATE",evidence,request("POST")));var duplicate=input();((ArrayNode)duplicate.get("observations")).add(duplicate.path("observations").get(0).deepCopy());assertThrows(DomainException.class,()->controller.write(null,"CREATE",duplicate,request("POST")));for(String key:List.of("AUTO_NORMAL","","unknown")){var v=input();((ObjectNode)v.path("observations").get(0)).put("result",key);assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}}
    @Test void nullObservationWrongTypesAndTooManyAnswersFail()throws Exception{for(String raw:List.of("null","{}","[null]","[42]")){var v=input();v.set("observations",mapper.readTree(raw));assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}var many=input();var rows=many.putArray("observations");for(int i=0;i<101;i++)rows.addObject().put("key","key_"+i).put("result","NORMAL").putNull("note");assertThrows(DomainException.class,()->controller.write(null,"CREATE",many,request("POST")));}
    @Test void emptyAnswersAreValidAndDoNotProduceNormalValues(){var v=input();v.putArray("observations");var d=data(controller.write(null,"CREATE",v,request("POST")));assertEquals(0,((List<?>)d.get("observations")).size());assertEquals(2,((Map<?,?>)d.get("summary")).get("unanswered"));assertEquals(false,((Map<?,?>)d.get("summary")).get("all_results_entered"));}
    @Test void explicitTimeRequiresTimezoneMillisecondsAndKeepsActualInstant(){for(String value:List.of("2026-01-01","2026-01-01T01:00:00","2026-01-01T01:00:00.1234Z","0000-01-01T00:00:00Z","not-time"))assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("reported_performed_at",value),request("POST")));var d=data(controller.write(null,"CREATE",input().put("reported_performed_at","2026-01-01T09:00:00.123+08:00"),request("POST")));assertEquals("2026-01-01T01:00:00.123Z",d.get("reported_performed_at"));assertEquals("SELF_REPORTED_TIME",d.get("time_source"));}
    @Test void notesKeepNullEmptyAndMultilineButRejectControlsAndOverlong(){for(String note:List.of("","　","  原文\n\t😀  ")){var v=input();((ObjectNode)v.path("observations").get(0)).put("note",note);var d=data(controller.write(null,"CREATE",v,request("POST")));assertEquals(note,((Map<?,?>)((List<?>)d.get("observations")).get(0)).get("note"));}for(String note:List.of("bad\u0000","bad\ud800","😀".repeat(3001))){var v=input();((ObjectNode)v.path("observations").get(0)).put("note",note);assertThrows(DomainException.class,()->controller.write(null,"CREATE",v,request("POST")));}}
    @Test void replayRunsAuthorizationWithoutExecutingMutation(){doAnswer(call->{((Runnable)call.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("original"));verify(repository).authorizeWrite(access(),ID);verify(repository,never()).archive(any(),any(),anyLong());}
    @Test void requestHashIgnoresObjectOrderButPreservesNullEmptyAndSourceVersion()throws Exception{var a=input();var b=(ObjectNode)mapper.readTree("{\"reported_performed_at\":null,\"observations\":[{\"note\":null,\"result\":\"ATTENTION\",\"key\":\"firmware\"}],\"template_version\":1,\"template_id\":\""+TEMPLATE+"\",\"asset_id\":\""+ASSET+"\",\"expected_version\":0}");var empty=a.deepCopy();((ObjectNode)empty.path("observations").get(0)).put("note","");for(var v:List.of(a,b,empty,a.deepCopy().put("template_version",2)))controller.write(null,"CREATE",v,request("POST"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(4)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));assertNotEquals(h.get(0),h.get(2));assertNotEquals(h.get(0),h.get(3));}
    @Test void listReturnsBoundedSummariesAndCompleteDetailHistoryAreReadOnly(){var row=row(1,"CREATE",false,new Content(Map.of(),null),definition());when(repository.list(eq(access()),isNull(),eq(View.CURRENT),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,row));var page=data(controller.list(request("GET")));assertEquals(true,page.get("has_more"));assertEquals(20,page.get("page_size_limit"));assertEquals(15,((List<?>)page.get("items")).size());var first=(Map<?,?>)((List<?>)page.get("items")).get(0);assertFalse(first.containsKey("observations"));assertFalse(first.containsKey("template_items"));when(repository.get(access(),ID)).thenReturn(row);assertEquals(2,((List<?>)data(controller.get(ID,request("GET"))).get("template_items")).size());when(repository.history(eq(access()),eq(ID),eq(16),isNull())).thenReturn(List.of(new Revision(1,null,ACTOR,row.recordedAt(),"CREATE",false,row.content())));assertEquals(false,data(controller.history(ID,request("GET"))).get("has_more"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void whitelistDuplicateCursorsAndOversizePageFail(){var unknown=request("GET");unknown.addParameter("tenant_id",TENANT);var duplicate=request("GET");duplicate.addParameter("page_size","10","15");var unpaired=request("GET");unpaired.addParameter("before_id",ID);var large=request("GET");large.addParameter("page_size","100");for(var r:List.of(unknown,duplicate,unpaired,large))assertThrows(DomainException.class,()->controller.list(r));var write=request("POST");write.addParameter("anything","x");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),write));}
    @Test void boundedParserRejectsDuplicateDeepTrailingOversizeAndMissingIdempotency(){for(String raw:List.of("{} {}","[[[[[1]]]]]","{\"observations\":[],\"observations\":[]}","{\"observations\":[{\"key\":\"a\",\"key\":\"b\"}]}"," ".repeat(InspectionWorksheetController.MAX_BODY_BYTES+1))){var r=request("POST");r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertThrows(DomainException.class,()->controller.create(r));}var r=request("POST");r.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),r));verifyNoInteractions(repository);}
    @Test void hundredMaximumUnicodeNotesFitLiteralUtf8BudgetButOversizeEscapesFail()throws Exception{var v=input();var rows=v.putArray("observations");var items=new ArrayList<InspectionTemplate.Item>();for(int i=0;i<100;i++){String key="item_"+i;rows.addObject().put("key",key).put("result","REQUIRES_ACTION").put("note","😀".repeat(3000));items.add(new InspectionTemplate.Item(key,"组","项",null));}var definition=new InspectionTemplate("custom","合成最大输入",items);doAnswer(call->row(1,"CREATE",false,((Creation)call.getArgument(2)).content(),definition)).when(repository).create(any(),anyLong(),any());var r=request("POST");byte[] utf8=mapper.writeValueAsString(v).getBytes(StandardCharsets.UTF_8);assertTrue(utf8.length<=InspectionWorksheetController.MAX_BODY_BYTES);r.setContent(utf8);assertEquals(100,((Map<?,?>)data(controller.create(r)).get("summary")).get("answered"));byte[] escaped=mapper.writeValueAsBytes(v);assertTrue(escaped.length>InspectionWorksheetController.MAX_BODY_BYTES);r.setContent(escaped);assertThrows(DomainException.class,()->controller.create(r));}
}
